import{inject}from'./vendor/analytics.js';
import{practicePool,practiceReport,remainingPractice}from'./practice.js';
import{CloudSync}from'./sync.js';
import{patchView,viewStore}from'./view.js';
import{chapterProgress,cleanProfile,avatarPresets,profileColors,authMessage}from'./product.js';
import{esc,localDay,answerSet,correct,flatten,shuffled,recordAnswer,score,get,put,entries,remove,restoreBackup,decrypt,unzip,encryptedFile}from'./core.js';
inject();
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 5c-3-2-7-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1zM12 5v15"/>',wrong:'<rect x="4" y="3" width="16" height="19" rx="3"/><path d="m9 9 6 6m0-6-6 6M9 3V1m6 2V1"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',chart:'<path d="M4 3v18h18M8 16v-4m5 4V7m5 9V4"/>',exam:'<rect x="4" y="4" width="16" height="17" rx="3"/><path d="M8 2h8v4H8zM8 11h8m-8 5h5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',check:'<path d="m5 12 4 4L19 6"/>',shuffle:'<path d="M3 6h3l12 12h3m-4-4 4 4-4 4M3 18h3L18 6h3m-4-4 4 4-4 4"/>',note:'<path d="M13 4H5v16h15v-8M10 14l1-5L19 1l4 4-8 8z"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',back:'<path d="m14 5-7 7 7 7"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',download:'<path d="M12 2v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',flag:'<path d="M5 22V3c5-4 9 4 14 0v11c-5 4-9-4-14 0"/>',compass:'<circle cx="12" cy="12" r="10"/><path d="m16 7-3 6-6 4 4-7z"/>',calendar:'<rect x="3" y="5" width="18" height="17" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${paths[n]||paths.book}</svg>`;
const button=(label,action,extra='',cls='btn')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const num=n=>Number(n||0).toLocaleString('zh-CN');
let manifest,key,catalog=[],records={},settings={rank:'三副',goal:50,font:18,dark:false},daily={},history=[],session=null,questions=[],bank=null,renderId=0,toastTimer,selection='',filter={rank:'',category:'',search:'',page:1},collectionFilter='wrong',searchTimer,busy=false;
const banks=new Map(),images=new Map();
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function fail(e){console.error(e);toast(e?.message||'操作未能完成，请重试');}
let displayedAccount=null,profile=cleanProfile(),profileDraft=null,lastRoute='',scrollSaving=false,viewTimer,remoteTimer;
const views=()=>viewStore(displayedAccount||'guest');
function saveView(route=lastRoute){if(!route||scrollSaving)return;const state=views().get(route);views().set(route,{...state,y:window.scrollY,questionSearch:$('#question-search')?.value??state.questionSearch,filter:{...filter}});}
function statusLabel(status=cloud.status){return status.startsWith('同步失败')?'同步暂缓':status;}
function updateStatus(){document.querySelectorAll('.status-dot,.cloud-state').forEach(el=>{const label=localStatus();if(el.textContent!==label)el.textContent=label;if(el.title!==cloud.status)el.title=cloud.status;});}
const cloud=new CloudSync(({user,changed})=>{
 updateStatus();if(!key||!changed)return;clearTimeout(remoteTimer);
 remoteTimer=setTimeout(()=>{actionQueue=actionQueue.then(async()=>{
  const switched=displayedAccount!==(user?.id||null);
  if(switched){saveView();displayedAccount=user?.id||null;session=null;questions=[];lastRoute='';await reloadLocalData();navigate('profile');return;}
  await reloadLocalData({preserveSession:true,preserveFilters:true});
  if(modal.open)return;
  if(location.hash==='#practice'){updateIdentity();return;}
  await render({preserve:true,background:true});
 }).catch(fail);},100);
});
const localStatus=()=>cloud.user?statusLabel():navigator.onLine?'本机自动保存':'离线可用';
function profileName(){return profile.nickname||cloud.user?.email?.split('@')[0]||'海行学员';}
function avatarMarkup(p=profile,cls=''){const photo=p.avatar.startsWith('data:');return '<span class="avatar '+cls+'" style="--avatar-color:'+p.color+'">'+(photo?'<img src="'+p.avatar+'" alt="个人头像">':esc(p.avatar))+'</span>';}
function updateIdentity(){document.querySelectorAll('[data-profile-name]').forEach(el=>{if(el.textContent!==profileName())el.textContent=profileName();});document.querySelectorAll('[data-profile-avatar]').forEach(el=>{const html=avatarMarkup();if(el.innerHTML!==html)el.innerHTML=html;});}
function accountPanel(){return `<section class="card card-pad account-card local-card"><div><span class="chip">${cloud.user?'多端已连接':'同步学习进度'}</span><h2>${cloud.user?esc(cloud.user.email):'登录后统一手机、网页与桌面版进度'}</h2><p>${cloud.user?'<span class="cloud-state">'+esc(localStatus())+'</span> · 离线记录联网后自动同步。':'无需登录也能离线刷题。登录后可同步错题、收藏、笔记、练习进度与小测记录。'}</p></div><div class="horizontal">${cloud.user?button('立即同步','cloud-sync','','btn secondary')+button('合并本机旧记录','cloud-import','','btn ghost')+button('退出账号','cloud-out','','btn ghost'):button('登录 / 注册','cloud-login')}${button('导出备份','backup','','btn secondary')}</div></section>`;}
function chapterRow(b,c,i){const p=chapterProgress(b.flat,records,c.id);return `<div class="chapter-group">${button(`<span class="chapter-ring ${p.pct===100?'complete':''}" role="progressbar" aria-label="${esc(c.name)}刷题进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.pct}" style="--progress:${p.pct}%"><span>${p.pct}%</span></span><span class="chapter-info"><h3>${esc(c.name)}</h3><small>已刷 ${num(p.learned)} / ${num(p.total)} 题</small></span>${icon('chevron')}`,'chapter',`data-key="${b.key}" data-chapter="${esc(c.id)}"`,'chapter-row')}</div>`;}
function profileHero(){return `<section class="card profile-hero"><div class="profile-banner"></div><div class="profile-intro">${avatarMarkup(profile,'large')}<div class="profile-heading"><span class="eyebrow">我的海行</span><h1>${esc(profileName())}</h1><p>${esc(profile.bio||'记录每一程的进步。')}</p><span class="chip">${esc(settings.rank)}</span></div>${button(`${icon('settings')} 编辑个人资料`,'edit-profile','','btn secondary')}</div><div class="profile-links">${button(`${icon('star')} 我的收藏`,'nav','data-route="favorites"','text-link')}${button(`${icon('wrong')} 错题复习`,'nav','data-route="wrong"','text-link')}${button(`${icon('exam')} 我的练习报告`,'profile-history','','text-link')}</div></section>`;}
function openProfileEditor(){
 profileDraft={...profile};openModal(`<h2>编辑个人资料</h2><p>让学习空间更像你。</p><div id="profile-avatar-preview">${avatarMarkup(profileDraft,'large')}</div><div class="avatar-options">${avatarPresets.map(v=>button(esc(v),'pick-avatar',`data-avatar="${v}" aria-label="使用${v}头像"`,'avatar-choice')).join('')}${button('上传照片','upload-avatar','','btn ghost')}</div><input id="profile-avatar-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><div class="field"><label for="profile-nickname">昵称</label><input id="profile-nickname" maxlength="24" value="${esc(profile.nickname)}" placeholder="怎么称呼你？" autocomplete="nickname"></div><div class="field"><label for="profile-bio">个人签名</label><textarea id="profile-bio" maxlength="120" class="note-input" placeholder="写下你的目标，或喜欢的一句话">${esc(profile.bio)}</textarea></div><fieldset class="profile-color-picker"><legend>头像背景</legend>${profileColors.map(c=>button('', 'pick-color',`data-color="${c}" aria-label="选择颜色 ${c}" style="background:${c}"`, 'color-choice')).join('')}</fieldset><p id="profile-error" role="alert"></p><div class="modal-actions">${button('取消','close-modal','','btn ghost')}${button('保存资料','save-profile')}</div>`,'profile-dialog');
}
async function profileAction(a,d){
 if(a==='edit-profile'){openProfileEditor();return true;}
 if(a==='pick-avatar'||a==='pick-color'){if(a==='pick-avatar')profileDraft.avatar=d.avatar;else profileDraft.color=d.color;$('#profile-avatar-preview').innerHTML=avatarMarkup(profileDraft,'large');return true;}
 if(a==='upload-avatar'){$('#profile-avatar-file').click();return true;}
 if(a==='save-profile'){const nickname=$('#profile-nickname').value.trim();if(!nickname){$('#profile-error').textContent='请填一个昵称';$('#profile-nickname').focus();return true;}profile=cleanProfile({...profileDraft,nickname,bio:$('#profile-bio').value});await put('settings','user-profile',profile);modal.close();await render({preserve:true});toast('个人资料已保存');return true;}
 if(a==='profile-history'){$('#learning-history')?.scrollIntoView({behavior:'smooth',block:'start'});return true;}
 return false;
}
async function readAvatar(file){
 if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type))throw Error('请选择 JPG、PNG、WebP 或 GIF 图片');
 if(file.size>5*1024*1024)throw Error('请选择 5 MB 以内的图片');
 const bitmap=await createImageBitmap(file),size=Math.min(bitmap.width,bitmap.height),canvas=document.createElement('canvas');canvas.width=192;canvas.height=192;
 canvas.getContext('2d').drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,192,192);bitmap.close();return canvas.toDataURL('image/webp',0.82);
}
async function cloudAction(a){
 if(a==='cloud-login'){if(!cloud.configured()){toast('同步服务正在准备中');return true;}openModal(`<h2>多端统一进度</h2><p>各设备登录同一个账号即可同步。首次登录后，可在“我的学习”中合并本机旧记录。</p><div class="field"><label for="cloud-email">邮箱</label><input id="cloud-email" type="email" autocomplete="username"></div><div class="field"><label for="cloud-password">密码</label><input id="cloud-password" type="password" minlength="8" autocomplete="current-password"></div><p id="cloud-error" role="alert"></p><div class="modal-actions">${button('关闭','close-modal','','btn ghost')}${button('注册账号','cloud-register','','btn secondary')}${button('登录','cloud-in')}</div>`);return true;}
 if(a==='cloud-in'||a==='cloud-register'){const email=$('#cloud-email').value.trim(),password=$('#cloud-password').value;if(!$('#cloud-email').checkValidity()||!email){$('#cloud-error').textContent='请填写有效的邮箱地址';return true;}if(password.length<(a==='cloud-register'?8:1)){$('#cloud-error').textContent=a==='cloud-register'?'请设置至少 8 位密码':'请输入密码';return true;}try{if(a==='cloud-in'){await cloud.signIn(email,password);modal.close();}else{const ready=await cloud.signUp(email,password);if(ready)modal.close();else $('#cloud-error').textContent='请到邮箱确认注册，然后回到这里登录。';}}catch(e){$('#cloud-error').textContent=authMessage(e);}return true;}
 if(a==='cloud-sync'){await cloud.sync();return true;}
 if(a==='cloud-out'){session=null;questions=[];await cloud.signOut();await reloadLocalData();navigate('profile');return true;}
 if(a==='cloud-import'){openModal(`<h2>合并这台设备的旧记录</h2><p>会将本机模式下的学习记录上传到当前账号，与云端记录合并。本机原记录保留；相同题目的旧答题次数按较大值保留，避免重复导入叠加。</p><div class="modal-actions">${button('取消','close-modal','','btn ghost')}${button('确认合并','cloud-import-confirm')}</div>`);return true;}
 if(a==='cloud-import-confirm'){modal.close();await cloud.importGuest();toast('旧记录已合并，'+cloud.status);return true;}
 return false;
}
function navigate(route){saveView();if(location.hash.slice(1)===route)render({preserve:true});else location.hash=route;}
function preference(){document.body.classList.toggle('dark',!!settings.dark);document.documentElement.style.setProperty('--text-size',`${settings.font}px`);}
async function saveSettings(){await put('settings','preferences',settings);preference();}
function openModal(html,cls=''){modal.className=cls;modal.innerHTML=html;modal.showModal();}
function head(eyebrow,title,subtitle='',right=''){return`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1>${subtitle?`<p class="subtitle">${esc(subtitle)}</p>`:''}</div>${right}</div>`;}
const empty=(title,desc,act='')=>`<div class="empty">${icon('book')}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${act}</div>`;
const stateOf=q=>records[q.uid]||{};
const activeRecords=()=>Object.values(records);
function stats(){const a=activeRecords(),attempts=a.reduce((n,r)=>n+(r.attempts||0),0),right=a.reduce((n,r)=>n+(r.correctCount||0),0);return{attempts,right,accuracy:attempts?Math.round(right/attempts*100):0,learned:a.filter(r=>r.attempts).length,wrong:a.filter(r=>r.wrong).length,favorites:a.filter(r=>r.favorite).length,due:a.filter(r=>r.wrong&&(r.due||0)<=Date.now()).length};}
function nav(active,mobile=false){const s=stats();let links=[['home','学习概览','home'],['catalog','全部题库','book'],['wrong','错题复习','wrong'],['favorites','收藏笔记','star'],['exams','模拟考试','exam'],['profile','我的学习','chart']];if(mobile)links=links.filter(x=>x[0]!=='favorites');return links.map(([id,label,i])=>button(`${icon(i)}<span>${label}</span>${!mobile&&id==='wrong'&&s.wrong?`<span class="badge">${s.wrong}</span>`:''}`,'nav',`data-route="${id}"`,`${mobile?'':'nav-button '}${active===id?'active':''}`)).join('');}
function shell(content,active='home'){
 const names={home:'学习概览',catalog:'全部题库',wrong:'错题复习',favorites:'收藏笔记',exams:'模拟考试',profile:'个人主页',bank:'科目学习',practice:'专注练习',result:'练习报告'};
 const crumb=active==='practice'&&bank?button(esc(catalog.find(b=>b.key===bank.key)?.name||'科目学习'),'nav','data-route="bank/'+bank.key+'"','breadcrumb-link')+' '+icon('chevron'):'';
 patchView(app,`<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="海行首页"><img src="/icon.svg" alt=""><div><strong>海行</strong><small>MARITIME STUDY</small></div></a><div class="nav-label">你的学习空间</div><nav class="nav-group">${nav(active)}</nav><div class="sidebar-bottom">${button('<span data-profile-avatar>'+avatarMarkup()+'</span><span class="identity"><strong data-profile-name>'+esc(profileName())+'</strong><small>'+esc(settings.rank)+' · 个人主页</small></span>'+icon('chevron'),'nav','data-route="profile" aria-label="打开个人主页"','user account-entry')}</div></aside><header class="topbar"><div class="breadcrumb">${button('海行学习空间','nav','data-route="home" aria-label="返回学习概览"','breadcrumb-link')} ${icon('chevron')} ${crumb}<b>${names[active]||'专注学习'}</b></div><div class="top-actions"><span class="status-dot" role="status">${localStatus()}</span>${button(avatarMarkup(),'nav','data-route="profile" aria-label="个人主页"','profile-shortcut')}${button(icon('sun'),'theme','aria-label="切换深浅外���"','icon-button')}</div></header><main class="main">${content}</main><nav class="mobile-nav" aria-label="主要导航">${nav(active,true)}</nav></div>`);loadImages();
}
function progressFor(b){const learned=activeRecords().filter(r=>r.uid?.startsWith(b.key+':')&&r.attempts).length;return{learned,pct:Math.min(100,Math.round(learned/b.total*100))};}
function bankCard(b){const p=progressFor(b);return button(`<div class="row"><span class="subject-icon">${icon(/英语/.test(b.name)?'book':/航海/.test(b.name)?'compass':/管理/.test(b.name)?'exam':'flag')}</span><span class="chip">${esc(b.rank)}</span></div><h3>${esc(b.name)}</h3><div class="bank-meta">${num(b.total)} 道题 · ${b.chapters.length} ${b.category==='冲刺密卷'?'套原卷':'个章节'}</div><div class="progress-track"><div class="progress-fill" style="width:${p.pct}%"></div></div><div class="bank-foot"><span>${p.learned?`已学习 ${num(p.learned)} 题`:'准备好，开始这一程'}</span><span>${p.pct}%</span></div>`,'open-bank',`data-key="${esc(b.key)}"`,'bank-card');}
function weekDays(){return Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return{key:localDay(d),label:['日','一','二','三','四','五','六'][d.getDay()]};});}
function dashboard(){const s=stats(),today=daily[localDay()]||{answered:0},recent=catalog.find(b=>b.key===(settings.lastPracticeBank||settings.lastBank)),recommended=catalog.filter(b=>b.category==='理论题库'&&b.rank===settings.rank).slice(0,4),target=recent||recommended[0]||catalog[0];const date=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});shell(`${head('A LITTLE PROGRESS, EVERY DAY','向着下一程，稳步前行','把每一道题的积累，变成出海时的底气。',`<div class="date-pill">${icon('calendar')}${date}</div>`)}<div class="dashboard-grid"><div><section class="hero"><div class="hero-art"></div><div><div class="tag">${recent?'CONTINUE YOUR JOURNEY':'YOUR NEXT CHAPTER'}</div><h2>${recent?'接着上次，继续进步':'今天，也离目标更近一点'}</h2><p>${esc(target?.name||'选择你的科目，开始学习')}<br>${recent?'你的练习进度已为你保留。':'从一个章节开始，建立自己的学习节奏。'}</p></div>${button(`${recent?'继续学习':'开始今日学习'} ${icon('arrow')}`,recent?'resume-bank':'open-bank',`data-key="${target?.key||''}"`,'btn white')}</section><div class="stats"><div class="stat"><div class="stat-top">累计练习 ${icon('book')}</div><strong>${num(s.learned)}</strong><small>题</small></div><div class="stat"><div class="stat-top">答题正确率 ${icon('chart')}</div><strong>${s.accuracy}<small>%</small></strong></div><div class="stat"><div class="stat-top">待复习错题 ${icon('wrong')}</div><strong>${num(s.wrong)}</strong><small>题</small></div></div><div class="section-head"><h2>我的科目 <small style="font-size:10px;margin-left:8px">${esc(settings.rank)}</small></h2>${button(`全部题库 ${icon('chevron')}`,'nav','data-route="catalog"','text-link')}</div><div class="bank-grid">${recommended.map(bankCard).join('')}</div><div class="section-head"><h2>学习足迹</h2>${button(`查看统计 ${icon('chevron')}`,'nav','data-route="profile"','text-link')}</div><div class="card card-pad"><div class="row"><div><h3 style="font-size:13px">保持节奏，积累看得见</h3><p class="meta-line" style="margin-top:8px">过去七天的答题记录</p></div><span class="chip">最近 7 天</span></div>${activityBars()}</div></div><aside class="dashboard-aside"><section class="card goal-card"><div class="goal-head"><h2>今日小目标</h2>${button('调整目标','goal','','text-link')}</div><div class="goal-ring" style="--progress:${Math.min(100,today.answered/settings.goal*100)}%"><div class="goal-center"><strong>${today.answered}</strong><span>/ ${settings.goal} 题</span></div></div><div class="goal-caption">${today.answered>=settings.goal?'今日目标已完成，做得很好。':'不必着急，每一步都算数。'}</div><div class="week">${weekDays().map(d=>`<i class="${daily[d.key]?.answered?'done':''}"><span>${d.label}</span><b>${daily[d.key]?.answered?'✓':'·'}</b></i>`).join('')}</div></section><section class="card quick-card"><h2 style="font-size:15px;margin-bottom:10px">复习工具箱</h2>${[['wrong','wrong','错题巩固',s.due?`${s.due} 道题等待复习`:'把薄弱处变成强项'],['favorites','star','我的收藏','值得再看一遍的知识'],['exams','exam','模拟考试','在出发前，检验准备']].map(([route,i,title,desc])=>button(`<span class="quick-icon">${icon(i)}</span><div><h3>${title}</h3><p>${desc}</p></div>${icon('chevron')}`,'nav',`data-route="${route}"`,'quick-row')).join('')}</section><section class="quote-card">${icon('compass')}<p>航向明确，步履不停。<br>远方，始于此刻的积累。</p><small>ONE QUESTION AT A TIME</small></section></aside></div>`,'home');}
function activityBars(){const days=weekDays(),max=Math.max(1,...days.map(d=>daily[d.key]?.answered||0));return`<div class="bars">${days.map(d=>`<div class="bar-wrap"><small>${daily[d.key]?.answered||0}</small><div class="bar" style="height:${Math.max(3,(daily[d.key]?.answered||0)/max*85)}px"></div><small>周${d.label}</small></div>`).join('')}</div>`;}
function catalogPage(){shell(`${head('YOUR STUDY LIBRARY','全部题库','选择职务与科目，开启属于你的学习计划。')}<div class="filters"><label class="search">${icon('search')}<input id="catalog-search" placeholder="搜索科目、版本或职务…" value="${esc(filter.search)}" aria-label="搜索题库"></label><select id="rank-filter" aria-label="筛选职务"><option value="">全部职务</option>${[...new Set(catalog.map(b=>b.rank))].map(r=>`<option ${r===filter.rank?'selected':''}>${esc(r)}</option>`).join('')}</select><select id="category-filter" aria-label="题库类型"><option value="">全部类型</option>${['理论题库','精选冲刺','冲刺密卷'].map(r=>`<option ${r===filter.category?'selected':''}>${r}</option>`).join('')}</select></div><div id="catalog-results">${catalogContents()}</div>`,'catalog');}
function catalogContents(){const list=catalog.filter(b=>(!filter.rank||b.rank===filter.rank)&&(!filter.category||b.category===filter.category)&&(!filter.search||`${b.name} ${b.rank} ${b.bankId}`.toLowerCase().includes(filter.search.toLowerCase())));filter.page=Math.max(1,Math.min(filter.page,Math.ceil(list.length/18)));return `<div class="section-head no-margin" style="margin-bottom:16px"><span class="meta-line">共 ${list.length} 套题库</span></div><div class="catalog-grid">${list.slice((filter.page-1)*18,filter.page*18).map(bankCard).join('')}</div>${list.length?'':empty('没有找到相关题库','换一个科目名称或筛选条件试试。')}${list.length>18?`<div class="pagination">${button('上一页','catalog-page',`data-delta="-1" ${filter.page===1?'disabled':''}`,'btn ghost')}<span>${filter.page} / ${Math.ceil(list.length/18)}</span>${button('下一页','catalog-page',`data-delta="1" ${filter.page*18>=list.length?'disabled':''}`,'btn ghost')}</div>`:''}`;}
function updateCatalog(){const el=$('#catalog-results');if(el)patchView(el,catalogContents());}
async function migrateAssociatedRecords(b){
 const groups=new Map();for(const q of b.flat)if(q.legacyUid){if(!groups.has(q.legacyUid))groups.set(q.legacyUid,new Map());groups.get(q.legacyUid).set(q.uid,q);}
 for(const [oldUid,candidates]of groups){const old=records[oldUid];if(!old?.title)continue;const matched=[...candidates.values()].filter(q=>(q.titleText??q.title)===old.title);if(matched.length!==1)continue;const q=matched[0];if(records[q.uid])continue;const migrated={...old,uid:q.uid,id:q.id};await put('records',q.uid,migrated);await remove('records',oldUid);records[q.uid]=migrated;delete records[oldUid];}
}
async function loadBank(id){if(banks.has(id))return banks.get(id);const meta=catalog.find(b=>b.key===id);if(!meta)throw Error('未找到这套题库');const data=await unzip(await decrypt(key,await encryptedFile('/vault/'+meta.file)));data.flat=flatten(data);await migrateAssociatedRecords(data);banks.set(id,data);if(banks.size>4)banks.delete(banks.keys().next().value);return data;}
async function bankPage(id,rid){if(!banks.has(id))shell(`${head('PREPARING YOUR CHAPTER','正在打开题库','只需加载当前科目，稍候即可开始。')}<div class="loading-line"></div>`,'catalog');const b=await loadBank(id);if(rid!==renderId)return;bank=b;if(settings.lastBank!==id){settings.lastBank=id;await saveSettings();}const meta=catalog.find(x=>x.key===id),saved=await get('sessions','bank:'+id);if(rid!==renderId)return;shell(`${head('FOCUS ON WHAT MATTERS',b.rank,'一个章节，一点进步。',button(`${icon('back')} 返回题库`,'nav','data-route="catalog"','btn ghost'))}<section class="card bank-hero"><div><span class="chip">${esc(meta.category)}</span><h1 style="margin-top:13px">${esc(meta.name)}</h1><p class="subtitle">${num(b.flat.length)} 道可练习题 · ${b.chapters.length} ${meta.category==='冲刺密卷'?'套原卷':'个章节'}</p></div>${button(`${saved?'继续上次练习':'顺序练习'} ${icon('arrow')}`,saved?'resume-bank':'start',`data-key="${id}" data-mode="sequence"`)}</section><div class="modes">${[['sequence','book','顺序练习','按章节循序渐进'],['random','shuffle','随机练习','打乱题序，检验掌握'],['memorize','eye','背题模式','答案与解析一起看'],['unseen','flag','未学题目','从没有做过的题开始'],['wrong','wrong','本科错题','反复巩固薄弱知识'],['favorites','star','收藏练习','温习重要考点'],['newest','clock','近期更新','按原题更新时间排序'],['exam','exam','模拟考试','限时作答，查看成绩']].map(([mode,i,title,desc])=>button(`${icon(i)}<b>${title}</b><small>${desc}</small>`,'start',`data-key="${id}" data-mode="${mode}"`,'mode-card')).join('')}</div>${customBankTools(id)}<div class="section-head"><h2>${meta.category==='冲刺密卷'?'原卷目录':'章节目录'}</h2><span class="meta-line">${num(b.flat.length)} 道题</span></div><label class="search" style="margin-bottom:18px">${icon('search')}<input id="question-search" placeholder="在本科目中搜索题干、选项或题号…" aria-label="搜索本题库题目"></label><div id="question-search-results"></div><div class="card" id="chapters">${b.chapters.map((c,i)=>chapterRow(b,c,i)).join('')}</div>`,'bank');}
async function start(id,mode='sequence',chapter=null,custom={}){if(busy)return;busy=true;try{const b=await loadBank(id);let list=b.flat.filter(q=>(chapter===null||String(q.chapterId)===String(chapter))&&(mode==='hidden'||!stateOf(q).hidden));if(mode==='wrong')list=list.filter(q=>stateOf(q).wrong);if(mode==='favorites')list=list.filter(q=>stateOf(q).favorite);if(mode==='unseen')list=list.filter(q=>!stateOf(q).attempts);if(mode==='hidden')list=list.filter(q=>stateOf(q).hidden);if(custom.config)list=practicePool(list,records,custom.config);if(mode==='newest')list.sort((a,b)=>String(b.modified||'').localeCompare(String(a.modified||'')));if(custom.ids)list=list.filter(q=>custom.ids.includes(q.uid));if(['random','exam'].includes(mode)&&!custom.original)list=shuffled(list);if(mode==='exam'&&!custom.count){busy=false;examModal(id,chapter);return;}if(custom.order==='random'&&mode!=='exam'&&mode!=='random')list=shuffled(list);if(custom.count)list=list.slice(0,custom.count);if(!list.length){toast('暂时没有符合条件的题目');return;}bank=b;questions=list;session={id:crypto.randomUUID(),bank:id,mode,chapter,title:custom.title||catalog.find(x=>x.key===id).name,indices:list.map(q=>q.occurrence),index:0,answers:{},graded:{},started:Date.now(),deadline:mode==='exam'?Date.now()+(custom.minutes||60)*60000:null,finished:false,viewed:{},scope:custom.scope||('scope:'+id+':'+(chapter??'all')+':'+mode),quiz:!!custom.quiz};await put('sessions','active',session);if(mode!=='exam')await put('sessions','bank:'+id,session);else await put('sessions','exam',session);settings.lastBank=id;if(mode!=='exam'){settings.lastPracticeBank=id;await put('sessions',session.scope,session);}await saveSettings();navigate('practice');}finally{busy=false;}}
function examModal(id,chapter=null){const b=banks.get(id),count=b.flat.filter(q=>chapter===null||String(q.chapterId)===String(chapter)).length;openModal(`<h2>${chapter?'原卷模拟':'自定义模拟考试'}</h2><p>计时开始后可暂时离开，倒计时仍会继续。交卷后统一查看答案与解析。</p><div class="field"><label for="exam-count">题目数量（最多 ${count} 道）</label><input id="exam-count" type="number" min="1" max="${count}" value="${chapter?count:Math.min(100,count)}"></div><div class="field"><label for="exam-minutes">考试时长（分钟）</label><input id="exam-minutes" type="number" min="1" max="360" value="60"></div><div class="modal-actions">${button('取消','close-modal','','btn ghost')}${button('开始考试','confirm-exam',`data-key="${id}" data-chapter="${chapter??''}"`)}</div>`);}
async function resume(id,scope=null){
 let saved=await get('sessions',scope||(id==='exam'?'exam':id?'bank:'+id:'active'));
 if(!saved&&id&&id!=='exam'&&!scope){const previous=history.find(h=>h.bank===id&&h.mode!=='exam');if(previous){saved=remainingPractice(previous);if(saved)await put('sessions','bank:'+id,saved);}}
 if(!saved||saved.finished){if(id&&id!=='exam'){await start(id);return;}navigate('catalog');return;}
 const loaded=await loadBank(saved.bank);
 if(saved.indices.some(i=>!loaded.flat[i]))throw Error('题库内容已变化，请重新选择练习范围');
 session=saved;bank=loaded;questions=saved.indices.map(i=>loaded.flat[i]);
 session.index=Math.max(0,Math.min(saved.index||0,questions.length-1));
 if(session.mode!=='exam'){settings.lastPracticeBank=session.bank;await saveSettings();}
 await saveSession();navigate('practice');
}
async function saveSession(){
 if(!session||session.finished)return;
 await put('sessions','active',session);
 if(session.mode==='exam'){await put('sessions','exam',session);return;}
 await put('sessions','bank:'+session.bank,session);
 if(session.scope)await put('sessions',session.scope,session);
}
function questionImages(q){return[...new Set([q.image,...(q.titleImages||[])].filter(Boolean))].map(imageTag).join('');}
function imageTag(id){if(images.has(id))return '<img class="q-image" src="'+images.get(id)+'" alt="题目配图" data-action="zoom">';return`<span class="image-loading" data-image="${esc(id)}">正在加载题目配图…</span>`;}
function math(text){return esc(text).replace(/\^\(([^)]+)\)/g,'<sup>$1</sup>').replace(/_\(([^)]+)\)/g,'<sub>$1</sub>');}
function analysis(q,value,memorize=false){return`<section class="analysis ${value&&!correct(q,value)?'wrong-answer':''}"><h3>${value?(correct(q,value)?'回答正确，继续保持':'再巩固一次，下次会更熟悉'):'答案与解析'}</h3><p>标准答案：<b>${esc(q.answer)}</b>${value?`　你的答案：${esc(value)}`:''}</p>${(q.analysis||[]).map(a=>`<h4>${esc(a.label||a.source||'题目解析')}</h4><p>${math((a.text||'').replace(/\[配图：[^\]]+\]/g,''))}</p>${(a.images||[]).map(imageTag).join('')}`).join('')||''}</section>`;}
function practicePage(){if(!session||!questions.length){resume().catch(fail);return;}const q=questions[session.index],s=stateOf(q),value=session.answers[session.index]||'',graded=session.graded[session.index],reveal=session.finished||session.mode==='memorize'||(session.mode!=='exam'&&graded),multi=answerSet(q.answer).length>1&&Object.keys(q.options||{}).length>0;selection=value;if(session.mode==='memorize'&&!session.finished){session.viewed||={};session.viewed[session.index]=true;}const completed=Object.values(session.answers).filter(Boolean).length;const title=session.mode==='exam'?(session.quiz?'小测':'模拟考试'):session.mode==='memorize'?'背题模式':'专注练习';shell(`${head('ONE QUESTION AT A TIME',title,session.title,button(`${icon('back')} 退出练习`,'leave-practice','','btn ghost'))}<div class="question-layout"><div><article class="card question-card"><div class="question-meta"><span class="type">${esc(q.typeName|| (multi?'多选题':'单选题'))}</span><span>${esc(q.chapter)} · ${session.index+1} / ${questions.length}</span></div>${q.parent?`<section class="context"><small>关联题材料</small><p>${math(q.parent.titleText??q.parent.title)}</p>${questionImages(q.parent)}</section>`:''}<h2 class="question-title">${math(q.titleText??q.title)}</h2>${questionImages(q)}<div class="options">${Object.entries(q.options||{}).map(([k,v])=>{const isAnswer=answerSet(q.answer).includes(k),selected=value.includes(k);return button(`<span class="letter">${esc(k)}</span><span class="option-content">${math(q.optionText?.[k]??v)}${(q.optionImages?.[k]||[]).map(imageTag).join('')}</span>`,'option',`data-value="${k}" ${reveal?'aria-disabled="true"':''}`,`option ${selected?'selected':''} ${reveal&&isAnswer?'correct':''} ${reveal&&selected&&!isAnswer?'wrong':''}`);}).join('')}</div>${!Object.keys(q.options||{}).length?`<div class="notice">此题没有选项，请先思考，再查看原题答案。</div>${button('查看答案','reveal','','btn secondary')}`:''}${multi&&!reveal?`<p class="meta-line" style="margin-top:15px">${session.mode==='exam'?'可选择多个选项，选择后自动保存。':'请选择所有正确选项，再确认答案。'}</p>${session.mode!=='exam'?button('确认答案','confirm-answer','style="margin-top:15px"'):''}`:''}${reveal?analysis(q,value,session.mode==='memorize'):''}<div class="question-actions">${button(`${icon('star')}${s.favorite?'已收藏':'收藏题目'}`,'favorite','',s.favorite?'on':'')}${button(`${icon('note')}${s.note?'编辑笔记':'写笔记'}`,'note')}${button(`${icon('eye')}${s.hidden?'取消隐藏':'隐藏此题'}`,'hidden')}${s.wrong?button(`${icon('check')}移出错题本`,'master'):''}</div>${s.note?`<div class="context"><small>我的笔记</small><p>${esc(s.note)}</p></div>`:''}<div class="question-bottom">${button(`${icon('back')}上一题`,'step',`data-delta="-1" ${session.index===0?'disabled':''}`,'btn ghost')}<small>题号 ${q.id}</small>${button(session.index===questions.length-1?(session.mode==='exam'&&!session.finished?'交卷':'完成练习'):`下一题 ${icon('arrow')}`,'step','data-delta="1"')}</div></article></div><aside><section class="card answer-card"><div class="row"><h2 style="font-size:15px">答题卡</h2><span class="meta-line">已答 ${completed} / ${questions.length}</span></div>${session.mode==='exam'&&!session.finished?'<div id="timer" class="timer">--:--</div>':''}<div class="answer-grid">${questions.slice(Math.floor(session.index/100)*100,Math.floor(session.index/100)*100+100).map((x,offset)=>{const i=Math.floor(session.index/100)*100+offset;const a=session.answers[i],isGraded=session.finished||(session.mode!=='exam'&&session.graded[i]);return button(i+1,'jump',`data-index="${i}" aria-label="第 ${i+1} 题"`, `answer-dot ${i===session.index?'current':''} ${a?(isGraded?(correct(x,a)?'good':'bad'):'answered'):''}`);}).join('')}</div>${questions.length>100?`<div class="horizontal" style="justify-content:space-between">${button('前 100 题','jump',`data-index="${Math.max(0,Math.floor(session.index/100)*100-100)}" ${session.index<100?'disabled':''}`,'text-link')}${button('后 100 题','jump',`data-index="${Math.min(questions.length-1,Math.floor(session.index/100)*100+100)}" ${Math.floor(session.index/100)*100+100>=questions.length?'disabled':''}`,'text-link')}</div>`:''}<p class="legend">${session.mode==='exam'&&!session.finished?'蓝色：已答　灰色：未答':'绿色：正确　橙色：需巩固'}<br>点击题号可快速跳转</p><div class="spacer"></div>${button(session.mode==='exam'&&!session.finished?'提交试卷':'结束本次练习','finish','','btn secondary full-width')}</section><div class="notice">${session.mode==='exam'?'交卷后查看成绩与逐题解析。':'答错的题会加入错题本，连续答对 3 次后自动移出。'}</div></aside></div>`,'practice');tick();}
async function persistRecord(q,patch){const next={...stateOf(q),...patch,id:q.id,uid:q.uid,bank:session.bank,title:q.titleText??q.title,bankName:session.title,rank:bank.rank};await put('records',q.uid,next);records[q.uid]=next;}
async function grade(value){const q=questions[session.index];if(session.graded[session.index])return;await persistRecord(q,recordAnswer(stateOf(q),q,value));const day=localDay(),d=daily[day]||{answered:0,correct:0};d.answered++;if(correct(q,value))d.correct++;daily[day]=d;await put('settings','daily',daily);session.graded[session.index]=true;await saveSession();}
async function choose(value){if(!session||session.finished||session.mode==='memorize'||(session.mode!=='exam'&&session.graded[session.index]))return;const q=questions[session.index],multi=answerSet(q.answer).length>1;if(multi){const chosen=new Set((session.answers[session.index]||'').split(''));chosen.has(value)?chosen.delete(value):chosen.add(value);session.answers[session.index]=[...chosen].sort().join('');}else session.answers[session.index]=value;await saveSession();if(!multi&&session.mode!=='exam')await grade(value);practicePage();}
async function finish(force=false){
 if(!session)return;
 if(session.finished){navigate('result/'+session.id);return;}
 const isExam=session.mode==='exam',unanswered=questions.length-Object.values(session.answers).filter(Boolean).length;
 if(isExam&&!force){openModal(`<h2>确认提交试卷？</h2><p>${unanswered?`还有 ${unanswered} 道未答，按本次试卷总题量计分。`:'所有题目已作答。'}交卷后统一查看解析。</p><div class="modal-actions">${button('继续答题','close-modal','','btn ghost')}${button('确认交卷','submit-exam')}</div>`);return;}
 if(busy)return;busy=true;
 try{
  if(isExam){for(let i=0;i<questions.length;i++){
   const q=questions[i],value=session.answers[i];
   if(!value)continue;
   const next={...recordAnswer(stateOf(q),q,value),bank:session.bank,title:q.titleText??q.title,bankName:session.title,rank:bank.rank};
   records[q.uid]=next;await put('records',q.uid,next);session.graded[i]=true;
  }
  const d=daily[localDay()]||{answered:0,correct:0};d.answered+=questions.length-unanswered;d.correct+=score(questions,session.answers).right;daily[localDay()]=d;await put('settings','daily',daily);
  }
  const report=practiceReport(session,questions);
  if(!report.indices.length){await saveSession();toast('本次还没有提交答案，已保留练习进度');return;}
  if(isExam){await remove('sessions','exam');await remove('sessions','active');}
  else{
   const remaining=remainingPractice(session);
   if(remaining){await put('sessions','bank:'+session.bank,remaining);if(session.scope)await put('sessions',session.scope,remaining);await put('sessions','active',remaining);}
   else{await remove('sessions','bank:'+session.bank);if(session.scope)await remove('sessions',session.scope);await remove('sessions','active');}
  }
  await put('history',report.id,report);history=history.filter(h=>h.id!==report.id);history.unshift(report);session=report;questions=report.indices.map(i=>bank.flat[i]);navigate('result/'+report.id);
 }finally{busy=false;}
}
async function resultPage(id,rid){const h=history.find(h=>h.id===id)||await get('history',id);if(!h){navigate('profile');return;}const b=await loadBank(h.bank),pending=await get('sessions','bank:'+h.bank);if(rid!==renderId)return;const qs=h.indices.map(i=>b.flat[i]).filter(Boolean),r=h.result||score(qs,h.answers);shell(`${head('YOUR LEARNING REPORT',h.mode==='exam'?'考试报告':'练习报告',h.title)}<div class="card result-score"><span class="chip">${h.mode==='exam'?'模拟考试 · 百分制自测':'本次练习结果'}</span><div><strong>${h.mode==='memorize'?r.total:r.score}</strong><small>${h.mode==='memorize'?'题':h.mode==='exam'?'分':'% 正确率'}</small></div><p>${h.mode==='memorize'?`本次浏览 ${r.total} 道题`:`${r.right} 道正确 / 本次 ${r.total} 道题 · ${r.answered} 道已答`}</p><p style="margin-top:8px">用时 ${Math.max(1,Math.round((h.finishedAt-h.started)/60000))} 分钟</p><div class="horizontal" style="justify-content:center;margin-top:25px">${h.mode!=='exam'&&pending&&!pending.finished?button('继续未完成部分','resume-bank',`data-key="${h.bank}"`,'btn ghost'):''}${button('逐题解析','review-history',`data-id="${h.id}"`)}${button('只复习错题','review-wrong',`data-id="${h.id}"`,'btn secondary')}</div></div><div class="section-head"><h2>题目回顾</h2><small>点击题号查看解析</small></div><div class="card card-pad"><div class="answer-grid" style="grid-template-columns:repeat(auto-fill,minmax(34px,1fr));max-height:none">${qs.map((q,i)=>button(i+1,'review-history',`data-id="${h.id}" data-index="${i}"`,`answer-dot ${correct(q,h.answers[i])?'good':'bad'}`)).join('')}</div></div>`,'result');}
function collectionPage(type){collectionFilter=type==='wrong'?'wrong':collectionFilter==='wrong'?'favorite':collectionFilter;const current=collectionFilter,labels={wrong:'错题复习',favorite:'我的收藏',note:'学习笔记',hidden:'已隐藏题目'};const rows=activeRecords().filter(r=>current==='wrong'?r.wrong:current==='favorite'?r.favorite:current==='note'?r.note:r.hidden).sort((a,b)=>(b.lastAt||0)-(a.lastAt||0)),groups=new Map();for(const r of rows){const group=groups.get(r.bank)||[];group.push(r);groups.set(r.bank,group);}shell(`${head('MAKE KNOWLEDGE YOUR OWN',type==='wrong'?'错题复习':'收藏与笔记',type==='wrong'?'把不熟悉的知识，变成下一次的胸有成竹。':'保存重要考点，也记下自己的理解。')}${type!=='wrong'?`<div class="segmented" style="margin-bottom:24px">${[['favorite','收藏题目'],['note','学习笔记'],['hidden','已隐藏']].map(([id,l])=>button(l,'collection-tab',`data-type="${id}"`,id===current?'active':'')).join('')}</div>`:`<div class="notice">答错即加入错题本；连续答对 3 次后自动移出。待复习时间根据你的回答情况安排。</div>`}<div class="section-head"><h2>${rows.length} 道${labels[current]}</h2><span class="meta-line">${groups.size} 个科目</span></div>${!rows.length?`<div class="card">${empty(type==='wrong'?'这里暂时没有错题':'还没有保存的内容',type==='wrong'?'开始练习后，答错的题会自动出现在这里。':'练习时点击收藏、笔记或隐藏按钮即可管理题目。',button('去选一门科目','nav','data-route="catalog"'))}</div>`:[...groups].map(([id,rs])=>`<section class="card" style="margin-bottom:20px"><div class="card-head" style="padding:21px 24px;margin:0;border-bottom:1px solid var(--line)"><div><h3 style="font-size:14px">${esc(rs[0].bankName)}</h3><p class="meta-line">${rs.length} 道 · ${esc(rs[0].rank)}</p></div>${button(current==='wrong'?'复习错题':'开始练习','start',`data-key="${id}" data-mode="${current==='favorite'?'favorites':current==='note'?'notes':current}"`,'btn secondary')}</div>${rs.slice(0,5).map(r=>`<div class="list-row"><span class="subject-icon">${icon(current==='wrong'?'wrong':current==='note'?'note':'star')}</span><div class="grow">${button(esc(String(r.title||'配图题').slice(0,120)),'open-question',`data-key="${id}" data-uid="${esc(r.uid)}"`,'text-button')}<p>${current==='note'?esc(String(r.note).slice(0,160)):current==='wrong'?`答错 ${r.wrongCount||0} 次 · ${r.streak||0}/3 次连续答对 · ${(r.due||0)<=Date.now()?'现在复习':new Date(r.due).toLocaleDateString('zh-CN')+' 再复习'}`:'已保存至你的学习空间'}</p></div></div>`).join('')}${rs.length>5?`<div class="meta-line" style="padding:17px 24px">还有 ${rs.length-5} 道题，点击开始练习查看全部。</div>`:''}</section>`).join('')}` ,type==='wrong'?'wrong':'favorites');}
async function examsPage(){const currentRender=renderId,ongoing=await get('sessions','exam');if(currentRender!==renderId)return;const papers=catalog.filter(b=>b.category==='冲刺密卷'&&b.rank===settings.rank);shell(`${head('PREPARE WITH CONFIDENCE','模拟考试','用一次完整练习，检验自己的准备。')}${ongoing?`<div class="notice row"><span>你有一份尚未提交的试卷：${esc(ongoing.title)}</span>${button('继续考试','resume-bank','data-key="exam"','btn secondary')}</div>`:''}<section class="hero" style="min-height:190px;margin-bottom:25px"><div class="hero-art"></div><h2>把考场，提前带到这里</h2><p>自选题量与时间，或使用已导出的原卷。<br>答题卡、倒计时、成绩与解析，一次完成。</p>${button(`选择科目开始 ${icon('arrow')}`,'nav','data-route="catalog"','btn white')}</section>${quizHub()}<div class="section-head"><h2>原卷模拟 · ${esc(settings.rank)}</h2>${button('其他职务','all-papers','','text-link')}</div><div class="catalog-grid">${papers.map(bankCard).join('')}</div><div class="section-head"><h2>考试记录</h2><span class="meta-line">自动保存，随时回顾</span></div>${historyList(history.filter(h=>h.mode==='exam'))}`,'exams');}
function historyList(list){return list.length?`<div class="card">${list.slice(0,30).map(h=>`<div class="list-row"><span class="history-score">${h.result?.score??0}<small>分</small></span><div class="grow"><h3>${esc(h.title)}</h3><p>${new Date(h.finishedAt).toLocaleString('zh-CN')} · ${h.result?.answered||0}/${h.result?.total||0} 道题</p></div>${button('查看报告','nav',`data-route="result/${h.id}"`,'btn ghost')}</div>`).join('')}</div>`:`<div class="card">${empty('还没有练习报告','完成一次练习或考试后，报告会保存在这里。')}</div>`;}
function profilePage(){const s=stats();shell(`${profileHero()}<div class="stats"><div class="stat"><div class="stat-top">学习天数 ${icon('calendar')}</div><strong>${Object.values(daily).filter(d=>d.answered).length}</strong><small>天</small></div><div class="stat"><div class="stat-top">累计答题 ${icon('book')}</div><strong>${num(s.attempts)}</strong><small>次</small></div><div class="stat"><div class="stat-top">正确率 ${icon('chart')}</div><strong>${s.accuracy}</strong><small>%</small></div></div>${accountPanel()}<div class="settings-grid"><section class="card card-pad"><h2>学习偏好</h2><div class="setting-row"><div><h3>当前职务</h3><p>用于首页推荐科目与原卷</p></div><select id="preferred-rank" aria-label="当前职务">${[...new Set(catalog.map(b=>b.rank))].map(r=>`<option ${r===settings.rank?'selected':''}>${esc(r)}</option>`).join('')}</select></div><div class="setting-row"><div><h3>每日目标</h3><p>循序渐进，养成练习习惯</p></div>${button(`${settings.goal} 题 / 天`,'goal','','btn ghost')}</div><div class="setting-row"><div><h3>题目字号</h3><p>选择适合你的阅读大小</p></div><select id="font-size" aria-label="题目字号">${[[16,'标准'],[18,'舒适'],[21,'大字'],[24,'特大']].map(([v,l])=>`<option value="${v}" ${settings.font===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting-row"><div><h3>深色外观</h3><p>晚上学习也舒适</p></div>${button(settings.dark?'已开启':'未开启','theme','','btn ghost')}</div></section><section class="card card-pad"><h2>数据与离线</h2><div class="setting-row"><div><h3>导出学习备份</h3><p>换设备前导出错题、收藏、笔记和进度</p></div>${button('导出','backup','','btn secondary')}</div><div class="setting-row"><div><h3>恢复学习备份</h3><p>将已有记录合并到当前浏览器</p></div>${button('导入','import','','btn ghost')}</div><div class="setting-row"><div><h3>离线保存本科目</h3><p>缓存上次打开科目的题目与配图</p></div>${button('缓存','cache-bank','','btn ghost')}</div><p class="meta-line">学习备份包含练习进度、收藏、笔记与个人设置。</p></section></div><div class="section-head" id="learning-history"><h2>最近学习记录</h2><span class="meta-line">最多显示最近 30 次</span></div>${historyList(history)}<section class="card card-pad product-about"><strong>海行</strong><p>为每一次学习留下进步。章节练习、错题巩固、小测与多端续练，在这里连接起来。</p></section>`,'profile');}
async function loadImages(){const nodes=[...document.querySelectorAll('[data-image]')];await Promise.allSettled(nodes.map(async node=>{const id=node.dataset.image;try{let url=images.get(id);if(!url){const bytes=await decrypt(key,await encryptedFile(`/vault/v1/images/${id}.data`));const a=new Uint8Array(bytes),type=a[0]===137?'image/png':a[0]===255?'image/jpeg':a[0]===71?'image/gif':'image/webp';url=URL.createObjectURL(new Blob([bytes],{type}));images.set(id,url);}if(node.isConnected){const img=document.createElement('img');img.className='q-image';img.src=url;img.alt='题目配图，点击放大';img.loading='lazy';img.dataset.action='zoom';node.replaceWith(img);}}catch{if(node.isConnected){node.textContent='配图加载失败，稍后可重试';node.className='notice';}}}));}
async function render({preserve=false,background=false}={}){
 if(!key)return;const rid=++renderId,route=location.hash.slice(1)||'home',same=route===lastRoute;
 const y=preserve||same?window.scrollY:views().get(route).y||0;
 if(lastRoute&&!same)saveView();lastRoute=route;scrollSaving=true;
 try{
  if(!background&&session&&!session.finished)await saveSession();
  if(route==='home')dashboard();else if(route==='catalog')catalogPage();else if(route==='wrong'||route==='favorites')collectionPage(route);else if(route==='exams')await examsPage();else if(route==='profile')profilePage();else if(route.startsWith('bank/'))await bankPage(route.slice(5),rid);else if(route==='practice'){if(!questions.length)await resume();else practicePage();}else if(route.startsWith('result/'))await resultPage(route.slice(7),rid);else dashboard();
  if(rid!==renderId)return;
  if(route.startsWith('bank/')){const term=same&&document.activeElement?.id==='question-search'?document.activeElement.value:views().get(route).questionSearch;if(term&&$('#question-search')){$('#question-search').value=term;searchQuestions(term);}}
  requestAnimationFrame(()=>{if(rid===renderId){window.scrollTo({top:y,behavior:'instant'});scrollSaving=false;saveView();}});
 }catch(e){scrollSaving=false;shell(empty('加载没有完成',e.message,button('重试','reload')),'catalog');fail(e);}
}
async function reloadLocalData({preserveSession=false,preserveFilters=false}={}){
 records=Object.fromEntries(await entries('records'));for(const b of banks.values())await migrateAssociatedRecords(b);settings={rank:'三副',goal:50,font:18,dark:false,...await get('settings','preferences')};profile=cleanProfile(await get('settings','user-profile')||{});plans=await get('settings','practice-plans')||[];daily=await get('settings','daily')||{};history=(await entries('history')).map(x=>x[1]).sort((a,b)=>(b.finishedAt||0)-(a.finishedAt||0));
 if(!preserveSession){session=await get('sessions','active')||null;questions=[];}
 if(!preserveFilters)filter={...filter,rank:settings.rank,...views().get('catalog').filter};preference();updateIdentity();
}
async function openVault(){catalog=await unzip(await decrypt(key,await encryptedFile('/vault/'+manifest.catalog)));await cloud.init();displayedAccount=cloud.user?.id||null;await reloadLocalData();await render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
async function exportBackup(){const stores={};for(const s of ['records','settings','sessions','history'])stores[s]=await entries(s);const blob=new Blob([JSON.stringify({app:'haixing-study',version:1,created:new Date().toISOString(),stores})],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`海行学习备份_${localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('学习备份已导出，请妥善保存');}
function tick(){if(!session||session.mode!=='exam'||session.finished)return;const left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000)),el=$('#timer');if(el)el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(!left&&key&&!busy){if(modal.open)modal.close();finish(true).then(()=>toast('考试时间结束，已自动交卷')).catch(fail);}}
setInterval(tick,1000);
let actionQueue=Promise.resolve();document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const originRoute=location.hash;const locked=['cloud-in','cloud-register','cloud-sync','cloud-out','save-profile','run-custom','save-plan','submit-exam','confirm-answer'].includes(el.dataset.action);if(locked)el.disabled=true;actionQueue=actionQueue.then(()=>handleAction(el,originRoute)).catch(fail).finally(()=>{if(locked&&el.isConnected)el.disabled=false;});});
async function handleAction(el,originRoute){const a=el.dataset.action,d=el.dataset;try{if(await profileAction(a,d))return;if(await cloudAction(a))return;if(await customAction(a,d))return;if(a==='nav'){navigate(d.route);return;}if(a==='open-bank'){navigate('bank/'+d.key);return;}if(a==='close-modal'){modal.close();return;}if(a==='reload'){render();return;}if(a==='theme'){settings.dark=!settings.dark;await saveSettings();await render({preserve:true});return;}if(a==='goal'){openModal(`<h2>设定每日小目标</h2><p>找到适合自己的节奏，每天多学一点。</p><div class="field"><label for="goal-input">每天练习题数</label><input id="goal-input" type="number" min="1" max="1000" value="${settings.goal}"></div><div class="modal-actions">${button('取消','close-modal','','btn ghost')}${button('保存目标','save-goal')}</div>`);return;}if(a==='save-goal'){const value=Number($('#goal-input').value);if(!Number.isInteger(value)||value<1||value>1000){toast('请输入 1 至 1000 之间的整数');return;}settings.goal=value;await saveSettings();modal.close();render();return;}if(a==='catalog-page'){filter.page+=Number(d.delta);updateCatalog();window.scrollTo({top:0,behavior:'smooth'});return;}if(a==='all-papers'){filter={rank:'',category:'冲刺密卷',search:'',page:1};navigate('catalog');return;}if(a==='start'){if(d.mode==='notes'){const ids=activeRecords().filter(r=>r.bank===d.key&&r.note).map(r=>r.uid);await start(d.key,'sequence',null,{ids});}else await start(d.key,d.mode);return;}if(a==='resume-bank'){await resume(d.key);return;}if(a==='chapter'){const saved=await get('sessions','scope:'+d.key+':'+d.chapter+':sequence');if(saved&&!saved.finished){await resume(d.key,saved.scope);return;}const meta=catalog.find(b=>b.key===d.key);if(meta.category==='冲刺密卷')examModal(d.key,d.chapter);else await start(d.key,'sequence',d.chapter);return;}if(a==='confirm-exam'){const count=Number($('#exam-count').value),minutes=Number($('#exam-minutes').value),max=Number($('#exam-count').max);if(!Number.isInteger(count)||count<1||count>max||!Number.isInteger(minutes)||minutes<1||minutes>360){toast('请填写有效的题量与时长');return;}modal.close();await start(d.key,'exam',d.chapter||null,{count,minutes,original:!!d.chapter,title:d.chapter?banks.get(d.key).chapters.find(c=>String(c.id)===d.chapter)?.name:undefined});return;}if(a==='option'){await choose(d.value);return;}if(a==='confirm-answer'){const value=session.answers[session.index];if(!value){toast('请先选择答案');return;}await grade(value);practicePage();return;}if(a==='reveal'){session.graded[session.index]=true;await saveSession();practicePage();return;}if(a==='step'){if(Number(d.delta)>0&&session.index===questions.length-1){await finish();return;}session.index=Math.max(0,Math.min(questions.length-1,session.index+Number(d.delta)));await saveSession();practicePage();window.scrollTo({top:0,behavior:'smooth'});return;}if(a==='jump'){session.index=Number(d.index);await saveSession();practicePage();return;}if(['favorite','hidden','master'].includes(a)){const q=questions[session.index],r=stateOf(q);await persistRecord(q,a==='favorite'?{favorite:!r.favorite}:a==='hidden'?{hidden:!r.hidden}:{wrong:false,streak:3});practicePage();toast(a==='master'?'已移出错题本':a==='hidden'?'已更新隐藏状态':'已更新收藏');return;}if(a==='note'){const q=questions[session.index];openModal(`<h2>写下你的理解</h2><p>题号 ${q.id} · 笔记只保存在你的学习空间</p><div class="spacer"></div><textarea id="note-text" class="note-input" maxlength="12000" placeholder="记住关键条件、判断思路或易错点…">${esc(stateOf(q).note||'')}</textarea><div class="modal-actions">${button('取消','close-modal','','btn ghost')}${button('保存笔记','save-note')}</div>`);return;}if(a==='save-note'){await persistRecord(questions[session.index],{note:$('#note-text').value});modal.close();practicePage();toast('笔记已保存');return;}if(a==='finish'){await finish();return;}if(a==='submit-exam'){modal.close();await finish(true);return;}if(a==='leave-practice'){await saveSession();if(location.hash===originRoute)navigate('bank/'+session.bank);toast(session.mode==='exam'&&!session.finished?'考试计时仍在继续':'进度已保存，下次可继续');return;}if(a==='review-history'){const h=await get('history',d.id);bank=await loadBank(h.bank);session=h;questions=h.indices.map(i=>bank.flat[i]).filter(Boolean);session.index=Number(d.index||0);navigate('practice');return;}if(a==='review-wrong'){const h=await get('history',d.id),b=await loadBank(h.bank);const ids=h.indices.map(i=>b.flat[i]).filter((q,i)=>q&&!correct(q,h.answers[i])).map(q=>q.uid);await start(h.bank,'sequence',null,{ids});return;}if(a==='collection-tab'){collectionFilter=d.type;collectionPage('favorites');return;}if(a==='open-question'){await start(d.key,'sequence',null,{ids:[d.uid]});return;}if(a==='backup'){await exportBackup();return;}if(a==='import'){$('#backup-file').click();return;}if(a==='zoom'){openModal(`<img src="${el.src}" alt="放大的题目配图"><div class="modal-actions">${button('关闭','close-modal','','btn ghost')}</div>`,'image-dialog');return;}if(a==='cache-bank'){if(!settings.lastBank){toast('请先打开需要离线学习的科目');return;}el.disabled=true;const b=await loadBank(settings.lastBank),ids=new Set();function scan(q){[q.image,...(q.titleImages||[]),...Object.values(q.optionImages||{}).flat(),...(q.analysis||[]).flatMap(x=>x.images||[])].filter(Boolean).forEach(id=>ids.add(id));q.children?.forEach(scan);}b.chapters.forEach(c=>c.questions.forEach(scan));let n=0,missing=0;for(const id of ids){try{await encryptedFile(`/vault/v1/images/${id}.data`);}catch{missing++;}n++;el.textContent=`${n}/${ids.size}`;}el.disabled=false;el.textContent='已缓存';toast(missing?`缓存完成，${missing} 张源配图不可用`:'本科目题目与配图已保存，可离线复习');return;}}catch(err){fail(err);}}
function searchQuestions(value){
 const box=$('#question-search-results'),chapters=$('#chapters');if(!box||!chapters||!bank)return;const term=value.trim().toLowerCase();
 if(!term){box.innerHTML='';chapters.hidden=false;return;}chapters.hidden=true;
 const list=bank.flat.filter(q=>`${q.id} ${q.titleText??q.title} ${Object.values(q.options||{}).join(' ')}`.toLowerCase().includes(term));
 box.innerHTML=`<p class="meta-line" style="margin-bottom:15px">找到 ${list.length} 道题${list.length>50?'，显示前 50 道':''}</p>${list.length?'<div class="card">'+list.slice(0,50).map(q=>'<div class="list-row"><div class="grow">'+button(esc((q.titleText??q.title).slice(0,180)),'open-question','data-key="'+bank.key+'" data-uid="'+q.uid+'"','text-button')+'<p>'+esc(q.chapter)+' · 题号 '+q.id+'</p></div></div>').join('')+'</div>':empty('没有找到相关题目','试试题号或更短的关键词')}`;
}
document.addEventListener('input',e=>{const el=e.target;if(el.id==='catalog-search'){filter.search=el.value;filter.page=1;updateCatalog();saveView();}if(el.id==='question-search'){clearTimeout(searchTimer);const route=location.hash;searchTimer=setTimeout(()=>{if(location.hash===route&&el.isConnected){searchQuestions(el.value);saveView();}},160);}});
document.addEventListener('change',async e=>{if(e.target.id!=='profile-avatar-file'||!e.target.files[0])return;try{profileDraft.avatar=await readAvatar(e.target.files[0]);if($('#profile-avatar-preview'))$('#profile-avatar-preview').innerHTML=avatarMarkup(profileDraft,'large');}catch(error){if($('#profile-error'))$('#profile-error').textContent=error.message;}finally{e.target.value='';}});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.id==='rank-filter'){filter.rank=el.value;filter.page=1;updateCatalog();}if(el.id==='category-filter'){filter.category=el.value;filter.page=1;updateCatalog();}if(el.id==='preferred-rank'){settings.rank=el.value;filter.rank=el.value;await saveSettings();await render({preserve:true});toast('推荐职务已更新');}if(el.id==='font-size'){settings.font=Number(el.value);await saveSettings();toast('字号已更新');}if(el.id==='backup-file'&&el.files[0]){await restoreBackup(JSON.parse(await el.files[0].text()));records=Object.fromEntries(await entries('records'));settings={...settings,...await get('settings','preferences')};daily=await get('settings','daily')||{};history=(await entries('history')).map(x=>x[1]).sort((a,b)=>b.finishedAt-a.finishedAt);session=null;questions=[];preference();el.value='';render();toast('备份已恢复');}}catch(e){fail(e);}});
window.addEventListener('hashchange',()=>render());window.addEventListener('scroll',()=>{clearTimeout(viewTimer);viewTimer=setTimeout(()=>saveView(),100);},{passive:true});window.addEventListener('pagehide',()=>saveView());window.history.scrollRestoration='manual';window.addEventListener('keydown',e=>{if(location.hash!=='#practice'||modal.open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')document.querySelector('[data-action="step"][data-delta="1"]')?.click();if(e.key==='ArrowLeft')document.querySelector('[data-action="step"][data-delta="-1"]')?.click();if(/^[a-f]$/i.test(e.key))document.querySelector(`[data-action="option"][data-value="${e.key.toUpperCase()}"]`)?.click();});
let plans=[],customDraft=null;
function customBankTools(id){return `<section class="card card-pad custom-tools"><div class="section-head no-margin"><div><h2>按自己的节奏练习</h2><p class="meta-line">选择章节、题量与出题范围，保存后可反复使用。</p></div><div class="horizontal">${button('自定义练习','custom',`data-key="${id}"`)}${button('已做题小测','custom',`data-key="${id}" data-kind="exam" data-source="learned"`,'btn secondary')}</div></div>${planList(id)}</section>`;}
function planList(id){const list=plans.filter(p=>!id||p.bank===id);return list.length?`<div class="saved-plans">${list.map(p=>`<div class="setting-row"><div><h3>${esc(p.name)}</h3><p>${p.kind==='exam'?'小测':'练习'} · ${p.count} 题 · ${p.chapters.length?p.chapters.length+' 个章节':'全部章节'} · ${esc({all:'全部题',learned:'已做题',wrong:'错题',favorites:'收藏',unseen:'未做题'}[p.source])}</p></div><div class="horizontal">${button('开始','run-plan',`data-id="${p.id}"`,'btn secondary')}${button('编辑','edit-plan',`data-id="${p.id}"`,'btn ghost')}${button('删除','delete-plan',`data-id="${p.id}"`,'btn ghost')}</div></div>`).join('')}</div>`:'';}
function quizHub(){const learned=catalog.filter(b=>activeRecords().some(r=>r.bank===b.key&&r.attempts));return `<section class="card card-pad custom-tools"><h2>已做题小测</h2><p class="subtitle">从之前真正作答过的题里出题，可按章节筛选或手动勾选。</p>${learned.length?`<div class="horizontal" style="margin-top:16px"><select id="quiz-bank" aria-label="小测科目">${learned.map(b=>`<option value="${esc(b.key)}">${esc(b.name)}</option>`).join('')}</select>${button('设置小测','quiz-hub')}</div>`:'<p class="notice">先完成几道练习，这里就会出现可用科目。</p>'}${planList()}</section>`;}
async function customModal(id,chapter=null,kind='practice',source='all',existing=null){
 const b=await loadBank(id);
 customDraft={bank:id,chapters:chapter===null?[]:[String(chapter)],kind,source,count:20,minutes:20,order:'random',name:'',...existing};
 const d=customDraft;
 openModal(`<h2>${existing?'编辑练习方案':kind==='exam'?'自定义小测':'自定义练习'}</h2><p>${esc(catalog.find(x=>x.key===id).name)} · 设置本次练习范围</p><div class="custom-fields"><div class="field"><label for="custom-kind">模式</label><select id="custom-kind"><option value="practice" ${d.kind==='practice'?'selected':''}>练习：每题即时解析</option><option value="exam" ${d.kind==='exam'?'selected':''}>小测：交卷后查看答案</option></select></div><div class="field"><label for="custom-source">出题范围</label><select id="custom-source">${Object.entries({all:'全部题目',learned:'之前做过的题',wrong:'当前错题',favorites:'收藏题目',unseen:'尚未做过的题'}).map(([v,t])=>`<option value="${v}" ${v===d.source?'selected':''}>${t}</option>`).join('')}</select></div></div><fieldset class="chapter-select"><legend>选择章节（不勾选表示全部）</legend>${b.chapters.map(c=>`<label><input type="checkbox" class="custom-chapter" value="${esc(c.id)}" ${d.chapters.map(String).includes(String(c.id))?'checked':''}>${esc(c.name)}</label>`).join('')}</fieldset><div class="custom-fields"><div class="field"><label for="custom-count">本次题量</label><input id="custom-count" type="number" min="1" max="1000" value="${d.count}"></div><div class="field"><label for="custom-order">题目顺序</label><select id="custom-order"><option value="random" ${d.order==='random'?'selected':''}>随机抽题</option><option value="sequence" ${d.order==='sequence'?'selected':''}>按原题顺序</option></select></div><div class="field"><label for="custom-minutes">小测时长（分钟）</label><input id="custom-minutes" type="number" min="1" max="360" value="${d.minutes}"></div><div class="field"><label for="custom-name">方案名称（保存时使用）</label><input id="custom-name" maxlength="60" value="${esc(d.name)}" placeholder="如：第一章每日 20 题"></div></div><p id="custom-pool" class="notice" aria-live="polite"></p><label class="horizontal"><input type="checkbox" id="custom-manual" ${d.ids?'checked':''}>手动勾选题目</label><div id="custom-picker" hidden><label class="search"><input id="custom-search" placeholder="按题号或题干搜索"></label><p class="meta-line">只从勾选的题目中抽题；可用搜索缩小范围。</p><div id="custom-questions"></div></div><div id="custom-error" role="alert" class="lock-error"></div><div class="modal-actions">${button('取消','close-modal','','btn ghost')}${button('保存方案','save-plan','','btn secondary')}${button('开始','run-custom')}</div>`,'custom-dialog');
 customDraft.selected=new Set(d.ids||[]);updateCustomPool();
}
function readCustom(){return {...customDraft,kind:$('#custom-kind').value,source:$('#custom-source').value,chapters:[...document.querySelectorAll('.custom-chapter:checked')].map(x=>x.value),count:Number($('#custom-count').value),minutes:Number($('#custom-minutes').value),order:$('#custom-order').value,name:$('#custom-name').value.trim()};}
function updateCustomPool(){
 if(!customDraft||!$('#custom-source'))return;
 const d=readCustom(),pool=practicePool(banks.get(d.bank).flat,records,{...d,ids:undefined});
 $('#custom-minutes').disabled=d.kind!=='exam';
 const manual=$('#custom-manual').checked;
 const n=manual?pool.filter(q=>customDraft.selected.has(q.uid)).length:pool.length;
 $('#custom-pool').textContent=`符合条件 ${pool.length} 道${manual?' · 已选 '+n+' 道':''}；本次将抽取 ${Math.min(Math.max(0,d.count||0),n)} 道。`;
 $('#custom-picker').hidden=!manual;
 if(manual){const term=$('#custom-search').value.trim().toLowerCase();const filtered=pool.filter(q=>`${q.id} ${q.titleText??q.title}`.toLowerCase().includes(term));$('#custom-questions').innerHTML=filtered.slice(0,200).map(q=>`<label class="pick-question"><input type="checkbox" data-pick="${esc(q.uid)}" ${customDraft.selected.has(q.uid)?'checked':''}><span><b>${esc(q.id)}</b> ${esc(String(q.titleText??q.title).slice(0,180))}</span></label>`).join('')+(filtered.length>200?'<p class="meta-line">显示前 200 道，请搜索题干或题号查找更多。</p>':'');}
}
function validateCustom(){const d=readCustom();delete d.selected;if($('#custom-manual').checked)d.ids=[...customDraft.selected];else delete d.ids;if(!Number.isInteger(d.count)||d.count<1||d.count>1000)throw Error('题量需要是 1–1000 的整数');if(d.kind==='exam'&&(!Number.isInteger(d.minutes)||d.minutes<1||d.minutes>360))throw Error('时长需要是 1–360 分钟');return d;}
async function runConfig(d){const b=await loadBank(d.bank),pool=practicePool(b.flat,records,d);if(!pool.length){toast('这个范围暂时没有可练习的题，请调整章节或出题范围');return;}if(d.count>pool.length)toast(`可用 ${pool.length} 道，已按实际题量开始`);modal.close();await start(d.bank,d.kind==='exam'?'exam':'sequence',null,{config:d,count:d.count,minutes:d.minutes,order:d.order,original:d.order==='sequence',quiz:d.kind==='exam',title:d.name||catalog.find(b=>b.key===d.bank).name,scope:d.id?'plan:'+d.id:undefined});}
async function customAction(a,d){
 if(a==='custom'){await customModal(d.key,d.chapter??null,d.kind||'practice',d.source||'all');return true;}
 if(a==='quiz-hub'){await customModal($('#quiz-bank').value,null,'exam','learned');return true;}
 if(a==='save-plan'||a==='run-custom'){try{const config=validateCustom();if(a==='save-plan'){config.id||=crypto.randomUUID();config.name||=`${config.kind==='exam'?'小测':'练习'} · ${config.count} 题`;plans=plans.filter(p=>p.id!==config.id);plans.push(config);await put('settings','practice-plans',plans);modal.close();await render();toast('方案已保存，可在科目页或模拟考试页再次使用');}else await runConfig(config);}catch(e){$('#custom-error').textContent=e.message;}return true;}
 if(a==='run-plan'){const plan=plans.find(p=>p.id===d.id),saved=await get('sessions','plan:'+d.id);if(saved&&!saved.finished)await resume(plan.bank,'plan:'+d.id);else await runConfig(plan);return true;}
 if(a==='edit-plan'){const p=plans.find(p=>p.id===d.id);await customModal(p.bank,null,p.kind,p.source,p);return true;}
 if(a==='delete-plan'){plans=plans.filter(p=>p.id!==d.id);await put('settings','practice-plans',plans);await render();toast('方案已删除，学习记录保留');return true;}
 return false;
}
document.addEventListener('change',e=>{if(!modal.open||!customDraft)return;if(e.target.dataset.pick){e.target.checked?customDraft.selected.add(e.target.dataset.pick):customDraft.selected.delete(e.target.dataset.pick);}if(e.target.closest('.custom-dialog'))updateCustomPool();});
document.addEventListener('input',e=>{if(e.target.id==='custom-search'||e.target.id==='custom-count')updateCustomPool();});

try{const r=await fetch('/vault/manifest.json?public=4',{cache:'no-store'});if(!r.ok)throw Error('题库配置尚未就绪');manifest=await r.json();if(!manifest.publicKey)throw Error('公开题库密钥尚未发布');key=await crypto.subtle.importKey('raw',Uint8Array.from(atob(manifest.publicKey),c=>c.charCodeAt(0)),{name:'AES-GCM'},false,['decrypt']);await openVault();}catch(e){app.innerHTML=`<div class="boot"><img src="/icon.svg" width="58" alt=""><h1>海行</h1><p>${esc(e.message)}</p><p>请检查网络后刷新页面。</p></div>`;}
